import{d as p,C as s,o as g,c as d,a3 as t,E as e,j as a,a as h}from"./chunks/framework.Q4yG9rk_.js";const y=JSON.parse('{"title":"正易心法·第三十九章","description":"《正易心法》第三十九章——一变为七，七变为九：引《冲虚经》「易变而为一，一变而为七，七变而为九，九复变而为一」，落到八宫卦「七变归魂、本宫之气革」的卦变周期，是第三十六章悬案的解答。","frontmatter":{"title":"正易心法·第三十九章","description":"《正易心法》第三十九章——一变为七，七变为九：引《冲虚经》「易变而为一，一变而为七，七变而为九，九复变而为一」，落到八宫卦「七变归魂、本宫之气革」的卦变周期，是第三十六章悬案的解答。","category":"guide","aliases":["正易心法第三十九章","一变为七七变为九","归魂与复变"],"source":["《正易心法》"],"outline":[2,3]},"headers":[],"relativePath":"yijing/zheng-yi-xin-fa/chapter-39.md","filePath":"yijing/zheng-yi-xin-fa/chapter-39.md","lastUpdated":1790647676000}'),c={name:"yijing/zheng-yi-xin-fa/chapter-39.md"},x=p({...c,setup(u){const i=[{id:"z39-01",label:"一、一变为七",showLabel:!0,sentences:[["一变为七，七变为九。即是",{text:"卦妄",glossary:"guawang"},"，宜究其实。"]],note:["一变为七、七变为九——这正是卦变的道理，应当追究其真实含义。（**本章解开了第三十六章留下的悬案**：第三十六章说「一变为七，七变为九。此之谓也」，**未给出出处**；本章引《冲虚经》，**原来那是《列子》的语言，不是麻衣自己的数字推演。**）"]},{id:"z39-02",label:"二、冲虚经之引",showLabel:!0,sentences:[["《",{text:"冲虚经",glossary:"chongxujing"},"》曰：《易》",{text:"无形埒",glossary:"wuxinglie"},"。易变而为一，一变而为七，七变而为九。九者，",{text:"究",glossary:"jiu"},"也，复变而为一。"]],note:["《冲虚经》（《列子》）说：《易》无形埒（没有形体的边界）。易变化而产生一，一变化而到达七，七变化而到达九。九，是穷尽之意，然后再变化回到一。（**《列子·天瑞》的宇宙生成序列**：无形之易 → 一 → 七 → 九（究）→ 复变为一。**这是宇宙从无到有、从有到极、从极返本的大循环。** 麻衣的贡献是：**把这个宇宙论模型，对应到八宫卦的变化次数（1→7→9→1）。**）"]},{id:"z39-03",label:"三、归魂与复变",showLabel:!0,sentences:[["盖卦爻自一变、二变、三变、四变、五变、六变、至七变，谓之",{text:"归魂",glossary:"guihun"},"，而",{text:"本宫之气革",glossary:"bengongZhiqiGe"},"矣。更二变而极于九，遂复变为一而",{text:"返本",glossary:"fanben"},"也。"]],note:["这是因为：卦爻从第一变、第二变、第三变、第四变、第五变、第六变，到第七变，称为「归魂」，此时本宫的气已经改变了；再经过两变而到达极点（第九变），于是再次变化回到一，返回根本。（**这是把《列子》的宇宙周期落到八宫卦上**：一（本卦）→ 七（归魂）→ 更二变极于九 → 复变为一。**「本宫之气革矣」是本章最耐人寻味的一句**：归魂听着像「回家」，**但回来的已不是原来那个**——**变化因此不是简单循环，而是螺旋。**）"]},{id:"z39-04",label:"四、溺空泛说",showLabel:!0,sentences:[["学者不悟经意",{text:"溺空泛说",glossary:"nikongFanshuo"},"，失之甚矣。"]],note:["学者不能领悟经典的真意，沉溺于空洞泛泛的说法，错得太厉害了。（**「失之甚矣」与第十三章「所失益甚矣」、第二十三章「失之远矣」同类**——都是麻衣对「空泛」的重话。**他的标准始终一致：任何概念都要有落处，没有落处的说法就是「空泛说」。**）"]}],o=[{id:"guawang",term:"卦妄",pinyin:"guà wàng",meaning:"卦变的道理。此处「妄」当读作「变」或「妄」之实义——即当究卦变的真实。"},{id:"chongxujing",term:"冲虚经",pinyin:"chōng xū jīng",meaning:"《列子》的道教尊称。唐代封《列子》为《冲虚真经》。"},{id:"wuxinglie",term:"无形埒",pinyin:"wú xíng liè",meaning:"没有形体的边界。埒＝界墙。《列子》语，指易的无形无界。"},{id:"jiu",term:"究",pinyin:"jiū",meaning:"穷尽、到头。九是极数，变化到了尽头，故「九者，究也」。"},{id:"guihun",term:"归魂",pinyin:"guī hún",meaning:"八宫卦第七变的名称：游魂卦再变，回归本宫。"},{id:"bengongZhiqiGe",term:"本宫之气革",pinyin:"běn gōng zhī qì gé",meaning:"本宫的气已经改变。革＝变革。七变后本宫气质已变——**回来的，已不是原来的那个**。"},{id:"fanben",term:"返本",pinyin:"fǎn běn",meaning:"返回根本。九变之后复归为一，循环完成。"},{id:"nikongFanshuo",term:"溺空泛说",pinyin:"nì kōng fàn shuō",meaning:"沉溺于空洞泛泛的说法。麻衣批评不究实义的学者。"}];return(b,n)=>{const r=s("DaoTextReading"),l=s("DaoKeywordCards");return g(),d("div",null,[n[0]||(n[0]=t(`<h1 id="正易心法·第三十九章" tabindex="-1">正易心法·第三十九章 <a class="header-anchor" href="#正易心法·第三十九章" aria-label="Permalink to &quot;正易心法·第三十九章&quot;">​</a></h1><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>本章有两个任务：</p><p><strong>任务一：解开第三十六章的悬案</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>第三十六章：「一变为七，七变为九。此之谓也。」（未给出处）</span></span>
<span class="line"><span>第三十九章：引《冲虚经》——「易变而为一，一变而为七，七变而为九」</span></span>
<span class="line"><span>= 那句话是在引用《列子·天瑞》，不是麻衣自己的数字推演</span></span></code></pre></div><p><strong>任务二：把宇宙论落实到卦变</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>《冲虚经》的宇宙周期：无形之易 → 一 → 七 → 九（究）→ 复变为一</span></span>
<span class="line"><span>八宫卦的变化次数：一变……至七变（归魂）→ 更二变极于九 → 复变为一（返本）</span></span>
<span class="line"><span>= 宇宙的大周期，就藏在每一次起卦的九变之中</span></span></code></pre></div><h2 id="为什么重要" tabindex="-1">为什么重要 <a class="header-anchor" href="#为什么重要" aria-label="Permalink to &quot;为什么重要&quot;">​</a></h2><p><strong>「一→七→九→一」的三重含义</strong>：</p><table tabindex="0"><thead><tr><th>层次</th><th>内容</th></tr></thead><tbody><tr><td><strong>宇宙论</strong>（《冲虚经》原意）</td><td>易（无）→ 一（有）→ 七（展开）→ 九（极）→ 一（返本）</td></tr><tr><td><strong>卦变论</strong>（麻衣的落处）</td><td>一（本卦）→ 七（归魂）→ 九（极变）→ 一（返本）</td></tr><tr><td><strong>数理论</strong>（前文的数字逻辑）</td><td>一（宗本）→ 七（少阳数）→ 九（老阳数）→ 一（返本）</td></tr></tbody></table><p><strong>三重含义的关系</strong>：<strong>同一个「一→七→九→一」，在三个层次上同时成立——这正是易学「象数合一」的典型结构。</strong></p><p><strong>「本宫之气革矣」——归魂的深意</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>「归魂」＝魂归本宫，字面意思是「回家了」</span></span>
<span class="line"><span>但麻衣说：「本宫之气革矣」——回来了，但气质已变</span></span>
<span class="line"><span></span></span>
<span class="line"><span>这是一个深刻的观察：</span></span>
<span class="line"><span>  经历了七次变化之后，即使形式上回到了原点，内在的气质已经不同了</span></span>
<span class="line"><span></span></span>
<span class="line"><span>就像：一个人历经风霜回到故乡，故乡还是那个故乡，但他已不是当年的那个他</span></span>
<span class="line"><span>= 变化不是简单的循环，而是螺旋式的上升（或下降）</span></span>
<span class="line"><span>  每一次「返本」，都是在更高（或更深）层次上的返本</span></span></code></pre></div><p><strong>「九者，究也」为什么九是极数？</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>数字层面：个位数中最大的奇数（阳数之极）</span></span>
<span class="line"><span>《易》层面：老阳之数＝九（极而必变）</span></span>
<span class="line"><span>卦变层面：九变＝八宫卦变化的极限（超过九变，已无新卦可生）</span></span>
<span class="line"><span>语言层面：「九」与「究」古音相近——九就是「究」</span></span></code></pre></div><p><strong>「溺空泛说」——麻衣批评的核心</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>把「一变为七，七变为九」当作纯粹的数字游戏，不知它对应八宫卦的具体变化次数 = 知其文，不知其义</span></span>
<span class="line"><span>把《冲虚经》的宇宙论当作玄虚的形而上学，不知它落实在具体的卦变操作里 = 知其玄，不知其实</span></span>
<span class="line"><span>把「归魂」只理解为「回归」，不知「本宫之气革矣」 = 知其名，不知其变</span></span></code></pre></div><h2 id="怎么读" tabindex="-1">怎么读 <a class="header-anchor" href="#怎么读" aria-label="Permalink to &quot;怎么读&quot;">​</a></h2><ol><li>先回看第三十六章的那句话，再看本章的出处；</li><li>再看「归魂」这个词的深意：<strong>归而不同</strong>；</li><li>最后读「溺空泛说」——<strong>这是麻衣对「空泛」的一贯批评。</strong></li></ol><h2 id="核心内容要点" tabindex="-1">核心内容要点 <a class="header-anchor" href="#核心内容要点" aria-label="Permalink to &quot;核心内容要点&quot;">​</a></h2><ul><li><strong>一变为七七变为九</strong>：引自《冲虚经》。</li><li><strong>无形埒</strong>：易的无边界。</li><li><strong>九者究也</strong>：九是极数。</li><li><strong>七变归魂</strong>：本宫之气革矣。</li><li><strong>更二变极于九</strong>：遂复变为一而返本。</li><li><strong>溺空泛说</strong>：不究实义之弊。</li></ul><h2 id="【原典层】原文" tabindex="-1">【原典层】原文 <a class="header-anchor" href="#【原典层】原文" aria-label="Permalink to &quot;【原典层】原文&quot;">​</a></h2>`,22)),e(r,{colophon:"一变为七 · 七变为九 · 七变归魂 · 复变返本",tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"正易心法第三十九章原文",sections:i,glossary:o}),n[1]||(n[1]=a("blockquote",null,[a("p",null,"注：本页依所据底本录入。原文「即是卦妄」之「妄」当读作实义（卦变之实），此处随底本，不作径改。")],-1)),n[2]||(n[2]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[h("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),e(l,{items:[{term:"冲虚经",pinyin:["chōng","xū"],meaning:"《列子》的道教尊称。本章所引「易变而为一，一变而为七，七变而为九」即出其中。"},{term:"无形埒",pinyin:["wú","xíng"],meaning:"没有形体的边界。「埒」是界墙——易无形界，故能为一切之始。"},{term:"一变为七七变为九",pinyin:["yī","biàn"],meaning:"第三十六章留下的悬案，本章给出出处：引自《列子·天瑞》。"},{term:"七变归魂",pinyin:["guī","hún"],meaning:"八宫卦第七变为归魂——魂归本宫，但「本宫之气革矣」，回来的已不是原来的那个。"},{term:"复变为一",pinyin:["fù","biàn"],meaning:"九变之后复归为一，返本还原，一个完整的变化周期结束。"}]}),n[3]||(n[3]=t(`<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一章在说什么" tabindex="-1">象：这一章在说什么 <a class="header-anchor" href="#象-这一章在说什么" aria-label="Permalink to &quot;象：这一章在说什么&quot;">​</a></h3><p>本章有两个任务：<strong>解第三十六章的悬案</strong>（「一变为七，七变为九」出自《冲虚经》）；<strong>把宇宙论落实到卦变</strong>（八宫卦的七变归魂、九变返本）。</p><h3 id="理-为什么这样说" tabindex="-1">理：为什么这样说 <a class="header-anchor" href="#理-为什么这样说" aria-label="Permalink to &quot;理：为什么这样说&quot;">​</a></h3><p><strong>「一→七→九→一」的三重含义</strong>：</p><table tabindex="0"><thead><tr><th>层次</th><th>内容</th></tr></thead><tbody><tr><td>宇宙论</td><td>易（无）→ 一（有）→ 七（展开）→ 九（极）→ 一（返本）</td></tr><tr><td>卦变论</td><td>一（本卦）→ 七（归魂）→ 九（极变）→ 一（返本）</td></tr><tr><td>数理论</td><td>一（宗本）→ 七（少阳数）→ 九（老阳数）→ 一（返本）</td></tr></tbody></table><p><strong>同一个「一→七→九→一」，在三个层次上同时成立</strong>——<strong>这正是易学「象数合一」的典型结构。</strong></p><p><strong>「本宫之气革矣」的深意</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>归魂 = 魂归本宫（回家了）</span></span>
<span class="line"><span>但「本宫之气革矣」——回来了，气质已变</span></span>
<span class="line"><span></span></span>
<span class="line"><span>= 变化不是简单的循环，而是螺旋式的返本</span></span></code></pre></div><h3 id="用-今天怎么进入这一章" tabindex="-1">用：今天怎么进入这一章 <a class="header-anchor" href="#用-今天怎么进入这一章" aria-label="Permalink to &quot;用：今天怎么进入这一章&quot;">​</a></h3><ul><li>回看第三十六章那句话，再看本章的出处——<strong>悬案就是这样解开的</strong>；</li><li>记住「归魂」的深意：<strong>归而不同</strong>；</li><li>顺着钩子想（承接昇哥的问题）：<strong>这是圆圈还是螺旋？</strong> 我的看法：<strong>麻衣说「本宫之气革矣」，这暗示他倾向于「螺旋」。</strong> 归魂不是简单的回归，是<strong>带着七变经历的回归</strong>。<strong>那么「复变而为一」之后的那个「一」，也不是最初的那个「一」，而是经历了九变的「一」。</strong> 这个「一」比最初的更丰富还是更空洞？<strong>麻衣没有回答——但「革」这个字给了方向：是「变」了，至于变好变坏，他不论。</strong> 或许这正是「未始有常」的意思：<strong>循环是形式，内容每一次都不同。</strong></li></ul><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>一变为七、七变为九——这正是卦变的道理，应当追究其真实含义。</p><p>《冲虚经》（《列子》）说：《易》无形埒（没有形体的边界）。易变化而产生一，一变化而到达七，七变化而到达九。九，是穷尽之意，然后再变化回到一。</p><p>这是因为：卦爻从第一变、第二变、第三变、第四变、第五变、第六变，到第七变，称为「归魂」，此时本宫的气已经改变了。再经过两变而到达极点（第九变），于是再次变化回到一，返回根本。</p><p>学者不能领悟经典的真意，沉溺于空洞泛泛的说法，错得太厉害了。</p><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><blockquote><p><strong>一句话</strong>：第三十九章做了一件「对齐」的工作——<strong>把《列子》的宇宙大周期，对齐到八宫卦的九次变化。</strong></p></blockquote><p>可以按这几条慢慢写：</p><ul><li><strong>悬案的解开</strong>——第三十六章那句「一变为七，七变为九」原来不是麻衣的数字推演，<strong>是引用《列子》。</strong> 这说明麻衣的视野<strong>超出易学</strong>：他用道家的宇宙论，为卦变体系提供形而上根据。</li><li><strong>三个层次同时成立</strong>——宇宙论、卦变论、数理论，<strong>同一个「一→七→九→一」。</strong> 这正是易学最擅长的「一理贯三层」。</li><li><strong>「本宫之气革矣」</strong>——<strong>这是我读完本章印象最深的一句。</strong> 「归魂」听起来是「回家」，但麻衣立刻补上：<strong>回来的，已不是原来那个。</strong> 就像河流绕一大圈回到源头——<strong>水还是水，但已流过了山川大地。</strong></li><li><strong>为什么引《列子》而不是《易》本身</strong>——这一点值得留意：<strong>麻衣在给《易》作注，却引道家的书来解。</strong> 在他的体系里，<strong>这不是「跨学科」，是「同一个东西的不同名字」。</strong></li><li><strong>「溺空泛说」</strong>——麻衣的批评一如既往地准：<strong>把宇宙论当玄谈（不知其实）、把数字当游戏（不知其义）、把归魂当回归（不知其变）。</strong> 三种「不知」，都是「没有落处」。</li><li><strong>留给自己的问题</strong>（承接昇哥的钩子）：<strong>这是圆圈还是螺旋？</strong> 我的看法：<strong>「本宫之气革矣」这五个字，暗示他倾向螺旋。</strong> 归魂不是简单的回归，<strong>是带着七变经历的回归。</strong> 那么「复变而为一」之后的那个「一」，<strong>也是经历了九变的「一」。</strong> 它比最初的更丰富还是更空洞？<strong>麻衣没有回答——但「革」这个字给了方向：是「变」了，至于变好变坏，他不论。</strong> 或许这正是「未始有常」：<strong>循环是形式，内容每一次都不同。</strong></li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="/Dao/yijing/zheng-yi-xin-fa/">正易心法总览</a></li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-36">第三十六章 · 策数六八</a> — 「一变为七，七变为九」（本章解其悬案）</li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-31">第三十一章 · 气数已尽</a> — 八宫八变（本章的归魂即第七变）</li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-19">第十九章 · 凡具八卦</a> — 一卦八变（同一体系）</li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-40">第四十章 · 名易之义</a> — 「易」是什么（本章的下一步）</li></ul>`,22))])}}});export{y as __pageData,x as default};
